CREATE TABLE cart_item(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,status VARCHAR(30),total DOUBLE,created_at TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE address(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,label VARCHAR(100),line1 VARCHAR(255),city VARCHAR(100),state VARCHAR(100),postal_code VARCHAR(30),country VARCHAR(100),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE review(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,rating INT,comment TEXT,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE notification(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(255),message TEXT,read_flag BOOLEAN,created_at TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
